-- Owner-requested catalogue refinement. Preserve historical products and orders.
begin;
update commerce.service_product_configs c set status='archived',
 customer_definition=c.customer_definition || '{"active":false,"channels":{"storefront":false,"guided":false,"advanced":false,"pos":false,"quote":false}}'::jsonb, updated_at=now()
from public.tenants t where c.tenant_id=t.id and t.slug='quick-solution' and c.source_key in ('folded-leaflets','booklets','notepads','presentation-folders','calendars','contravision-installation');
update commerce.products p set status='archived',updated_at=now()
from public.tenants t where p.tenant_id=t.id and t.slug='quick-solution' and p.slug in ('folded-leaflets','booklets','notepads','presentation-folders','calendars','contravision-installation');

update commerce.service_product_configs c set customer_definition='{"id":"car-magnets","name":"Car Magnets","shortName":"Car Magnets","category":"Signs & Large Format","description":"Removable printed vehicle advertising magnets.","plainDescription":"Removable printed vehicle advertising magnets. Configure your request; we confirm the quote before payment.","keywords":["car magnets","car magnets"],"active":true,"popular":false,"serviceType":"print-signage","channels":{"storefront":true,"guided":true,"advanced":false,"pos":false,"quote":true},"guidedJourneyId":"car-magnets-guided","nextActionLabel":"Request a quote","pricingVersion":"2026-10-catalogue-01","pricing":{"strategy":"ENQUIRY","quoteRequired":true},"fields":[{"id":"size","type":"select","label":"Magnet size","default":"500x300","options":[{"id":"500x300","label":"500 × 300 mm"},{"id":"custom","label":"Custom — enter measurements below"}]},{"id":"customSize","type":"textarea","label":"Custom dimensions in mm","placeholder":"Width × height for each magnet, if custom."},{"id":"quantity","type":"number","label":"How many sets of two?","default":1,"min":1,"max":10000,"step":1,"required":true},{"id":"vehicle","type":"textarea","label":"Vehicle and placement","placeholder":"Make/model, door or panel location. Attach a photo for suitability review."},{"id":"artwork","type":"select","label":"What about the design?","default":"ready","options":[{"id":"ready","label":"My artwork is ready"},{"id":"check","label":"Please check my artwork"},{"id":"design","label":"I need design help"}]},{"id":"brief","type":"textarea","label":"Anything we should know?","placeholder":"Intended use, deadline, measurements or finishing requirements."},{"id":"file","type":"file","label":"Artwork or reference","help":"Upload a PDF, image or photo of the installation area."}],"productPage":{"headline":"Car Magnets","intro":"Removable printed vehicle advertising magnets.","showStartingPrice":false}}'::jsonb,updated_at=now()
from public.tenants t where c.tenant_id=t.id and t.slug='quick-solution' and c.source_key='car-magnets';
update commerce.products p set name='Car Magnets',description='Removable printed vehicle advertising magnets.',updated_at=now()
from public.tenants t where p.tenant_id=t.id and t.slug='quick-solution' and p.slug='car-magnets';

