update commerce.products p set name='Shop Signs & Rigid Signage',description='Configure a printed sign, frame and installation request.',updated_at=now()
from public.tenants t where p.tenant_id=t.id and t.slug='quick-solution' and p.slug='rigid-signage';

update commerce.service_product_configs c set customer_definition='{"id":"contravision","name":"Contravision Window Printing","shortName":"Contravision","category":"Signs & Large Format","description":"Full-colour perforated window vinyl, supplied as a rectangular print for one panel.","plainDescription":"Enter one panel’s width and height. Print only, minimum 1 m² billed. Application is an optional separately quoted add-on based on the job. Car Contravision needs a vehicle-specific quote.","active":true,"popular":false,"keywords":["contravision","window branding","one way vision"],"channels":{"storefront":true,"guided":true,"pos":true,"quote":true},"guidedJourneyId":"contravision-guided","nextActionLabel":"Continue to collection","pricingVersion":"2026-10-contravision-local-02","pricing":{"strategy":"PER_AREA","baseRate":300,"minimumBillableArea":1,"unit":"m²"},"fields":[{"id":"width","type":"number","label":"Finished width","suffix":"metres","default":1,"min":0.1,"max":20,"step":0.01,"required":true},{"id":"height","type":"number","label":"Finished height","suffix":"metres","default":1,"min":0.1,"max":20,"step":0.01,"required":true},{"id":"material","type":"select","label":"Material","default":"standard","options":[{"id":"standard","label":"Perforated one-way-vision vinyl","multiplier":1}]},{"id":"finishing","type":"select","label":"Supply format","default":"print-only","options":[{"id":"print-only","label":"Rectangular print only — no fitting","fee":0}]},{"id":"artwork","type":"select","label":"What about the design?","default":"ready","options":[{"id":"ready","label":"My artwork is ready","fee":0},{"id":"check","label":"Please check my artwork","fee":75},{"id":"design","label":"I need design help","fee":250}]},{"id":"turnaround","type":"select","label":"Turnaround","default":"standard","options":[{"id":"standard","label":"Standard — timing confirmed after artwork review","multiplier":1}]},{"id":"file","type":"file","label":"Artwork or reference","help":"Upload a PDF, image or photo of the installation area."}],"productPage":{"headline":"Print your window branding","intro":"Live price for rectangular print supply. Request shop-window application as an add-on, or a separate Car Contravision quote for a shaped vehicle window.","showStartingPrice":true},"media":{"hero":"/qs-catalogue/contravision-v1.webp","gallery":[]}}'::jsonb,updated_at=now()
from public.tenants t where c.tenant_id=t.id and t.slug='quick-solution' and c.source_key='contravision';
update commerce.products p set name='Contravision Window Printing',description='Full-colour perforated window vinyl, supplied as a rectangular print for one panel.',updated_at=now()
